import{_ as a,o as r,c as t,ak as i}from"./chunks/framework.B8jO0odJ.js";const m=JSON.parse('{"title":"Chainy — Simplified Game Design Document","description":"Status: Proposed replacement GDD pending owner approval  \\nGame: Chainy  \\nFormat: Offline single-player 3D educational adventure  \\nAudience: Ages 12–17  \\nPlatform: Android, lan","frontmatter":{"title":"Chainy — Simplified Game Design Document","description":"Status: Proposed replacement GDD pending owner approval  \\nGame: Chainy  \\nFormat: Offline single-player 3D educational adventure  \\nAudience: Ages 12–17  \\nPlatform: Android, lan","source":"docs/archive/pre-lesson-collection-2026-11-11/game-design-simplified-draft.md","category":"Archive","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-lesson-collection-2026-11-11/game-design-simplified-draft.md","filePath":"content/docs/archive/pre-lesson-collection-2026-11-11/game-design-simplified-draft.md"}'),n={name:"content/docs/archive/pre-lesson-collection-2026-11-11/game-design-simplified-draft.md"};function o(s,e,l,d,c,h){return r(),t("div",null,[...e[0]||(e[0]=[i(`<div><h1 id="chainy--simplified-game-design-document">Chainy — Simplified Game Design Document<a class="header-anchor" href="#chainy--simplified-game-design-document" aria-label="Link to this section">​</a></h1><p><strong>Status:</strong> Proposed replacement GDD pending owner approval<br><strong>Game:</strong> Chainy<br><strong>Format:</strong> Offline single-player 3D educational adventure<br><strong>Audience:</strong> Ages 12–17<br><strong>Platform:</strong> Android, landscape, English-first</p><h2 id="1-game-overview">1. Game overview<a class="header-anchor" href="#1-game-overview" aria-label="Link to this section">​</a></h2><p>Chainy is a short linear learning adventure about Web3, blockchain and artificial intelligence fundamentals. The player explores three compact 3D worlds, follows one guided quest in each world, plays a subject-specific mini-game and earns a badge that unlocks the next world.</p><p>The structure is inspired by the short, progressive lesson pattern used by Giggle Academy: explain one idea, let the learner act on it, provide friendly feedback and continue along a visible learning path. Chainy does not copy Giggle Academy&#39;s characters, interface, lessons or artwork.</p><p>The game is not an economy simulator, real blockchain application or AI service. Its purpose is to make a small set of introductory concepts understandable through play.</p><h2 id="2-player-experience">2. Player experience<a class="header-anchor" href="#2-player-experience" aria-label="Link to this section">​</a></h2><h3 id="core-loop">Core loop<a class="header-anchor" href="#core-loop" aria-label="Link to this section">​</a></h3><ol><li>See one clear objective.</li><li>Explore a short route to the guide or learning station.</li><li>Read a brief explanation and example.</li><li>complete a mini-game round using that idea.</li><li>Receive an explanation for the result and retry when necessary.</li><li>Answer one new review item.</li><li>Earn the world badge, save progress and unlock the next world.</li></ol><h3 id="linear-progression">Linear progression<a class="header-anchor" href="#linear-progression" aria-label="Link to this section">​</a></h3><pre><code class="language-text">Web3 World → Blockchain World → AI World → Journey Complete
</code></pre><p>Each world contains one guide, one main quest, three short teaching beats, one mini-game and one final review. A world should take approximately 8–12 minutes. Completed worlds may be replayed, but optional exploration is not required for progression.</p><h3 id="shared-rules">Shared rules<a class="header-anchor" href="#shared-rules" aria-label="Link to this section">​</a></h3><ul><li>The current objective and destination are always visible.</li><li>The guide is visible or clearly signposted from the arrival point.</li><li>Dialogue appears over the live 3D world and temporarily disables movement.</li><li>Wrong answers do not remove progress or resources.</li><li>Feedback states what was wrong, gives one useful explanation and permits retry.</li><li>The final review uses a new example rather than repeating an answered card.</li><li>Completing a world awards one badge; there are no currencies, shops or inventories.</li></ul><h2 id="3-worlds-and-learning-content">3. Worlds and learning content<a class="header-anchor" href="#3-worlds-and-learning-content" aria-label="Link to this section">​</a></h2><h3 id="31-web3-world--restore-the-connection">3.1 Web3 World — Restore the Connection<a class="header-anchor" href="#31-web3-world--restore-the-connection" aria-label="Link to this section">​</a></h3><p><strong>Guide:</strong> Sean<br><strong>Goal:</strong> Help Sean restore a safe connection terminal.<br><strong>Learning outcome:</strong> The learner distinguishes public information from secret credentials, recognizes a token as a digital unit or item, and checks important transaction details before approval.</p><p><strong>Teaching beats</strong></p><ol><li><strong>Address station:</strong> A public address can be shared to receive something; a private key, password or recovery secret must not be shared.</li><li><strong>Token station:</strong> A token can represent a digital unit, access right or item, but does not automatically guarantee financial value or copyright ownership.</li><li><strong>Transaction station:</strong> The player checks the destination, item or amount and any displayed fee before choosing Confirm or Cancel.</li></ol><p><strong>Mini-game — Safe or Unsafe</strong></p><p>The player places action cards into <strong>Safe</strong> or <strong>Unsafe</strong> slots. Example cards include sharing a public receiving address, revealing a private credential, checking the destination and approving an unfamiliar request. Every card receives a short explanation.</p><p><strong>Completion:</strong> Correctly resolve the activity cards and one new review scenario. The connection terminal activates, the Web3 badge is awarded and Blockchain World unlocks.</p><h3 id="32-blockchain-world--repair-the-chain">3.2 Blockchain World — Repair the Chain<a class="header-anchor" href="#32-blockchain-world--repair-the-chain" aria-label="Link to this section">​</a></h3><p><strong>Guide:</strong> Matthew<br><strong>Goal:</strong> Repair a damaged local record display.<br><strong>Learning outcome:</strong> The learner explains that records can be grouped into linked blocks and uses a trusted reference to detect an altered record.</p><p><strong>Teaching beats</strong></p><ol><li><strong>Block station:</strong> A block groups records and includes information that helps identify its contents.</li><li><strong>Link station:</strong> Each displayed block refers to the previous block, creating an ordered chain.</li><li><strong>Verification station:</strong> Changing a record can create a mismatch, but a trusted checkpoint or reference is needed to decide which copy is expected.</li></ol><p><strong>Mini-game — Build the Chain</strong></p><p>The player places three block cards in the correct order using their previous-block references, then compares two versions and selects the altered field. The activity is a local teaching simulation, not a real distributed blockchain or consensus network.</p><p><strong>Completion:</strong> Build the sequence, identify the mismatch and answer one new verification scenario. The beacon activates, the Blockchain badge is awarded and AI World unlocks.</p><h3 id="33-ai-world--teach-and-check-the-bot">3.3 AI World — Teach and Check the Bot<a class="header-anchor" href="#33-ai-world--teach-and-check-the-bot" aria-label="Link to this section">​</a></h3><p><strong>Guide:</strong> Lee<br><strong>Goal:</strong> Help Lee prepare a supervised helper robot.<br><strong>Learning outcome:</strong> The learner distinguishes examples, labels and predictions, and recognizes that AI outputs can be wrong and require human checking.</p><p><strong>Teaching beats</strong></p><ol><li><strong>Example station:</strong> Training examples contain information paired with useful labels.</li><li><strong>Pattern station:</strong> A model uses patterns from examples to produce a prediction for a new case.</li><li><strong>Review station:</strong> Limited or misleading examples can contribute to mistakes; important outputs require human review.</li></ol><p><strong>Mini-game — Teach and Check the Bot</strong></p><p>The player labels example cards, inspects the bot&#39;s simulated predictions for new cards and accepts or corrects each result. Unless the implementation genuinely trains a small model from the player&#39;s labels, the interface calls the bot a <strong>simulation</strong>, not a trained AI.</p><p><strong>Completion:</strong> Label the examples, check the simulated predictions and answer one new limitations scenario. The assistance station activates, the AI badge is awarded and the journey-complete screen appears.</p><h2 id="4-shared-gameplay-systems">4. Shared gameplay systems<a class="header-anchor" href="#4-shared-gameplay-systems" aria-label="Link to this section">​</a></h2><h3 id="exploration-and-controls">Exploration and controls<a class="header-anchor" href="#exploration-and-controls" aria-label="Link to this section">​</a></h3><ul><li>Fixed orthographic isometric camera; no camera rotation.</li><li>Left virtual joystick for movement.</li><li>One contextual Interact button.</li><li>Back/Pause closes the active overlay or pauses play.</li><li>No jumping, combat, platforming, branching paths or precision movement.</li></ul><p>The three worlds are compact guided spaces built from a reusable environment kit. Exploration connects learning activities; it must not become a maze or a separate challenge.</p><h3 id="reusable-mini-game-framework">Reusable mini-game framework<a class="header-anchor" href="#reusable-mini-game-framework" aria-label="Link to this section">​</a></h3><p>All three mini-games use the same card interaction foundation:</p><ul><li>Tap a card to select it.</li><li>Tap a slot, position or answer to place it.</li><li>Submit the current round.</li><li>Show correct/incorrect state using text and icons as well as color.</li><li>Display a short explanation.</li><li>Retry incorrect cards without restarting the world.</li></ul><p>World-specific content changes the rule: Web3 sorts safety decisions, Blockchain orders and compares records, and AI labels examples and checks predictions.</p><h3 id="progress-and-saving">Progress and saving<a class="header-anchor" href="#progress-and-saving" aria-label="Link to this section">​</a></h3><p>The minimum saved state is:</p><ul><li>Current world and current quest step</li><li>Completed teaching beats</li><li>Completed mini-game and review</li><li>Earned world badges</li><li>Unlocked worlds</li></ul><p>Progress is stored locally and works without internet. Closing and reopening the game must restore the same objective, badges and unlocked world. A local profile is not an online account and does not recover progress on another phone.</p><h3 id="feedback-and-rewards">Feedback and rewards<a class="header-anchor" href="#feedback-and-rewards" aria-label="Link to this section">​</a></h3><ul><li>Use encouragement, explanation and retry rather than punishment.</li><li>Do not use lives, energy, purchasable hints, random rewards or leaderboards.</li><li>Award exactly one badge per completed world.</li><li>Badges show completion only; they do not claim mastery or learning improvement.</li></ul><h2 id="5-visual-and-interface-direction">5. Visual and interface direction<a class="header-anchor" href="#5-visual-and-interface-direction" aria-label="Link to this section">​</a></h2><p>Retain Chainy&#39;s fixed isometric, stylized low-poly presentation, blue-haired yellow-clad Explorer and friendly screen-faced robot guides. Each world uses a distinct subject color and landmark while sharing environment pieces and interface layouts.</p><p>The exploration HUD contains only the objective, movement control, Interact button and Pause button. Dialogue uses the approved live-world overlay. Mini-games use a single reusable card panel with world-specific labels and illustrations.</p><p>Text must remain readable on the minimum Android reference phone. Essential information must work with audio muted, and color must never be the only indicator of correctness.</p><h2 id="6-scope-boundary">6. Scope boundary<a class="header-anchor" href="#6-scope-boundary" aria-label="Link to this section">​</a></h2><h3 id="required-first-version">Required first version<a class="header-anchor" href="#required-first-version" aria-label="Link to this section">​</a></h3><ul><li>Three small ordered 3D worlds</li><li>One guided quest per world</li><li>Three teaching beats per world</li><li>One subject mini-game per world using the shared card framework</li><li>Explanatory feedback and supported retry</li><li>One fresh review item per world</li><li>Three completion badges and linear unlocking</li><li>Reliable offline local saving</li><li>World restoration or activation after completion</li></ul><h3 id="not-part-of-the-first-version">Not part of the first version<a class="header-anchor" href="#not-part-of-the-first-version" aria-label="Link to this section">​</a></h3><ul><li>Real wallets, cryptocurrency, payments or public blockchain connections</li><li>Coin economy, shops, inventory or equipment</li><li>NFT ownership system, exchanges, smart contracts or seed-phrase recovery</li><li>Mining, validators, multiple simulated nodes or general block editors</li><li>Cloud AI, generative chat or autonomous agents</li><li>Standalone Wordle or BlockMatch modes</li><li>Combat, open-world exploration, collectibles or branching quests</li><li>Multiplayer, rankings, teacher dashboard or online accounts</li></ul><p>These exclusions do not prevent later lessons from explaining additional terms. They prevent those terms from becoming required software systems in the first version.</p><h2 id="7-acceptance-criteria">7. Acceptance criteria<a class="header-anchor" href="#7-acceptance-criteria" aria-label="Link to this section">​</a></h2><table><thead><tr><th>ID</th><th>The design is accepted when</th></tr></thead><tbody><tr><td>GDD-01</td><td>A new player can complete Web3 → Blockchain → AI through one visible linear path.</td></tr><tr><td>GDD-02</td><td>Each world has exactly one main quest, three teaching beats, one mini-game and one fresh review.</td></tr><tr><td>GDD-03</td><td>All mini-games use the shared select/place/submit/feedback/retry framework.</td></tr><tr><td>GDD-04</td><td>Each incorrect response provides an explanation and a retry without permanent penalty.</td></tr><tr><td>GDD-05</td><td>Web3 distinguishes public receiving information from private credentials and asks the player to review before approval.</td></tr><tr><td>GDD-06</td><td>Blockchain links three blocks and requires a trusted reference when identifying the altered copy.</td></tr><tr><td>GDD-07</td><td>AI distinguishes examples, labels and predictions and shows that a prediction can require human correction.</td></tr><tr><td>GDD-08</td><td>The game does not request real credentials, make real transactions or represent a scripted bot as trained AI.</td></tr><tr><td>GDD-09</td><td>Completing each world changes its visible landmark, awards one badge and unlocks only the next world.</td></tr><tr><td>GDD-10</td><td>Relaunching offline restores the same objective, completion state, badges and unlocked worlds.</td></tr><tr><td>GDD-11</td><td>Gameplay remains usable with audio muted and without relying on color alone.</td></tr><tr><td>GDD-12</td><td>The GDD contains game behavior and scope only; schedules, staffing and task assignments remain in planning documents.</td></tr></tbody></table><h2 id="8-approval-assumptions">8. Approval assumptions<a class="header-anchor" href="#8-approval-assumptions" aria-label="Link to this section">​</a></h2><p>This draft assumes:</p><ol><li>One quest and one mini-game per world are sufficient for the first complete game.</li><li>The three activities may reuse one card interaction framework.</li><li>Badges and world unlocking replace the wallet economy and inventory.</li><li>Ages 12–17, English, offline Android and a 30–40 minute total journey remain the targets.</li></ol><p>Owner approval or correction of these four assumptions is required before this document replaces the current canonical GDD.</p></div>`,1)])])}const g=a(n,[["render",o]]);export{m as __pageData,g as default};
